using BenchmarkDotNet.Attributes;
using NCalc;
using NCalc.Benchmarks;
using NCalc.Extensions;
using Parlot.Fluent;

namespace Parlot.ExternalBenchmarks;

/// <summary>
/// Parses NCalc expressions with the same grammar compiled two ways: NCalc's shipping parser, generated by
/// Parlot.SourceGenerator, and the Parlot runtime (Fluent) graph that NCalc's own benchmarks compare it with.
/// </summary>
public class NCalcParse
{
    internal static readonly Dictionary<string, string> Expressions = new()
    {
        // From NCalc's ParserGenerationBenchmark
        ["Simple"] = "(3.2 < waterlevel AND 5.3 >= waterlevel)",
        ["Advanced"] = "PageState == 'LIST' && a == 1 && customFunction() == true || in(1 + 1, 1, 2, 3) && Name == 'Sergio'",
        // Every precedence level, from the ternary down to the unary operators
        ["Arithmetic"] = "[x] * (3 + 4.5) - 10 / 5 % 3 + Pow(2, 8) - -[y] << 2 >= 100 && !([z] | 3 & 5 ^ 1 != 0) ? Abs(-[x]) : 0",
        // A longer expression, as generated by rule engines
        ["Long"] = string.Join(" + ", Enumerable.Range(1, 40).Select(i => $"([a{i}] * {i} - [b{i}] / 2.5)")),
    };

    private readonly LogicalExpressionParserOptions _options = new();
    private readonly CultureInfo _culture = CultureInfo.InvariantCulture;
    private Parser<LogicalExpression> _fluent;

    [ParamsSource(nameof(Names))]
    public string Expression { get; set; }

    public static IEnumerable<string> Names => Expressions.Keys;

    private string _text;

    [GlobalSetup]
    public void Setup()
    {
        _fluent = FluentExpressionParser.Create(_options, _culture);
        _text = Expressions[Expression];

        if (typeof(LogicalExpressionParser).Assembly.GetReferencedAssemblies().Any(x => x.Name == "Parlot"))
        {
            throw new InvalidOperationException("NCalc's generated parser should not depend on the Parlot runtime.");
        }

        var generated = Generated().ToExpressionString();
        var fluent = Fluent().ToExpressionString();

        if (generated != fluent)
        {
            throw new InvalidOperationException($"The generated and Fluent parsers disagree:\n{generated}\n{fluent}");
        }
    }

    [Benchmark]
    public LogicalExpression Generated() => LogicalExpressionParser.Parse(_text, _options, _culture, CancellationToken.None);

    [Benchmark]
    public LogicalExpression Fluent()
    {
        // As NCalc's benchmark does: loop detection is disabled for this grammar
        var context = new ParseContext(new Scanner(_text), useNewLines: false, disableLoopDetection: true, CancellationToken.None);

        return _fluent.TryParse(context, out var result, out var error)
            ? result
            : throw new InvalidOperationException(error?.Message);
    }
}
